package com.hms.service; import com.hms.dao.BillingDao; import com.hms.model.Billing; import java.math.BigDecimal; import java.sql.SQLException; import java.util.List; public class BillingService{private final BillingDao dao;public BillingService(BillingDao d){dao=d;}public List<Billing> findAll()throws SQLException{return dao.findAll();}public Billing save(Billing b)throws SQLException{return dao.save(b);}public static BigDecimal total(BigDecimal c,BigDecimal s,BigDecimal d,BigDecimal t){return c.add(s).add(t).subtract(d);}}
